<script lang="ts">import {position,colors} from '../charts';let {value,scale,range,color=colors.mint}:{value:number|null,scale:[number,number],range:[number,number]|null,color?:string}=$props();</script><div class="rb">{#if range}<u style:left={position(range[0],scale)+'%'} style:width={(position(range[1],scale)-position(range[0],scale))+'%'}></u>{/if}{#if value!=null}<i style:left={position(value,scale)+'%'} style:background={color}></i>{/if}</div><style>.rb{position:relative;height:8px;border-radius:4px;background:rgba(255,255,255,.06)}u{position:absolute;top:0;bottom:0;border-radius:4px;background:rgba(61,220,151,.30)}i{position:absolute;top:50%;width:12px;height:12px;border-radius:50%;transform:translate(-50%,-50%);box-shadow:0 0 0 3px #10141F}</style>